pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address attacker, bytes calldata data) public {
        vm.assume(attacker != address(0) && attacker != address(c));
        // Deploy a fresh attacker contract whose _fallback writes msg.sender into slot 0 (owner slot)
        // to capture delegatecall context overwrite
        Attacker a = new Attacker();
        // record initial owner of C (should be this test contract via setUp)
        address initialOwner = c.owner();
        // prank as attacker to call forward with attacker address as callee
        vm.prank(attacker);
        // use data that will trigger the attacker's fallback
        bytes memory payload = abi.encodeWithSignature("overwrite()");
        c.forward(address(a), payload);
        // After call, owner must be unchanged in correct C; delegatecall changes it in buggy C
        assertTrue(c.owner() == initialOwner);
    }
}

contract Attacker {
    fallback() external {
        // In delegatecall context, this writes to slot 0 of the calling contract (C's owner)
        assembly {
            sstore(0, caller())
        }
    }
}

